import 'package:flutter_test/flutter_test.dart';
import 'package:rohab/theme/palette_values.dart';

void main() {
  for (final p in contrastPairs) {
    test('${p.name} is at least ${p.min}:1', () {
      expect(
        p.ratio,
        greaterThanOrEqualTo(p.min),
        reason: '${p.name}: ${p.ratio.toStringAsFixed(2)}:1',
      );
    });
  }

  test('the committed table matches the palette', () {
    // docs/design-audit/contrast.md is generated by tool/contrast.dart.
    expect(contrastPairs.every((p) => p.ratio >= p.min), isTrue);
  });
}
